import { World } from '@iwsdk/core';
import { GameSystem } from './game-system';
import { RenderSystem } from './render-system';
import { InputSystem } from './input-system';
import { UISystem } from './ui-system';
import { AudioSystem } from './audio-system';
import { EffectsSystem } from './effects-system';
import { EnvironmentSystem } from './environment-system';

async function main() {
  const container = document.getElementById('scene-container') as HTMLDivElement;
  const world = await World.create(container, {
    xr: { offer: 'once' },
    render: {
      near: 0.1,
      far: 200,
      camera: { position: [2, 5.5, 5], lookAt: [0, 1.2, 1.2] },
    },
    input: { canvasPointerEvents: true },
    features: {
      locomotion: false,
    },
  });

  world.registerSystem(EnvironmentSystem);
  world.registerSystem(GameSystem);
  world.registerSystem(RenderSystem);
  world.registerSystem(InputSystem);
  world.registerSystem(AudioSystem);
  world.registerSystem(EffectsSystem);
  world.registerSystem(UISystem);
}

main().catch(console.error);

// Shared game state — imported by every system

export const PYRAMID_ROWS = 7;
export const CUBE_SIZE = 0.6;
export const STRIDE = 0.8;
export const PILLAR_HEIGHT = 0.4;
export const ROW_DROP = 0.5;
export const HOP_DURATION = 0.3;

export type GameMode = 'arcade' | 'speed' | 'zen' | 'challenge';
export type Difficulty = 'easy' | 'medium' | 'hard';
export type ColorScheme = 'cyan' | 'green' | 'magenta' | 'gold';
export type Screen = 'menu' | 'playing' | 'paused' | 'results' | 'settings' | 'tutorial' | 'stats' | 'achievements';

export interface CubeData {
  row: number;
  col: number;
  colorState: number;
  targetState: number;
}

export interface EnemyData {
  type: 'coily' | 'slick' | 'sam';
  row: number;
  col: number;
  active: boolean;
  isEgg: boolean;
  moveTimer: number;
}

export interface Achievement {
  id: string;
  name: string;
  desc: string;
  unlocked: boolean;
}

export interface CareerStats {
  gamesPlayed: number;
  roundsCleared: number;
  enemiesDefeated: number;
  cubesHopped: number;
  highScore: number;
}

export interface GameState {
  screen: Screen;
  mode: GameMode;
  difficulty: Difficulty;
  colorScheme: ColorScheme;
  round: number;
  score: number;
  lives: number;
  playerRow: number;
  playerCol: number;
  hopping: boolean;
  hopProgress: number;
  hopFromRow: number;
  hopFromCol: number;
  hopToRow: number;
  hopToCol: number;
  cubes: CubeData[];
  enemies: EnemyData[];
  discLeft: boolean;
  discRight: boolean;
  discUsed: boolean;
  timer: number;
  hopsRemaining: number;
  totalHops: number;
  roundComplete: boolean;
  gameOver: boolean;
  deathAnimating: boolean;
  deathTimer: number;
  enemySpawnTimer: number;
  soundEnabled: boolean;
  musicEnabled: boolean;
  stats: CareerStats;
  achievements: Achievement[];
  achievementPage: number;
  pendingInput: { dr: number; dc: number } | null;
  initialized: boolean;
  combo: number;
  maxCombo: number;
  comboTimer: number;
  powerUps: PowerUp[];
  activePowerUp: ActivePowerUp | null;
  powerUpSpawnTimer: number;
  shieldActive: boolean;
  roundAnnounceTimer: number;
  freezeActive: boolean;
  scoreBoostActive: boolean;
}

export const COLOR_SCHEMES: Record<ColorScheme, { start: number; target: number; mid: number; accent: number; bg: number }> = {
  cyan:    { start: 0x1a1a3a, target: 0x00ffff, mid: 0x007777, accent: 0x00cccc, bg: 0x000a14 },
  green:   { start: 0x1a3a1a, target: 0x00ff88, mid: 0x007744, accent: 0x00cc66, bg: 0x000a08 },
  magenta: { start: 0x3a1a3a, target: 0xff00ff, mid: 0x770077, accent: 0xcc00cc, bg: 0x140014 },
  gold:    { start: 0x3a3a1a, target: 0xffcc00, mid: 0x776600, accent: 0xccaa00, bg: 0x141000 },
};

export function defaultAchievements(): Achievement[] {
  return [
    { id: 'first_hop', name: 'First Hop', desc: 'Complete your first hop', unlocked: false },
    { id: 'painter_10', name: 'Cube Painter', desc: 'Change 10 cubes', unlocked: false },
    { id: 'round_1', name: 'Round One', desc: 'Complete Round 1', unlocked: false },
    { id: 'round_5', name: 'Five Alive', desc: 'Complete 5 rounds', unlocked: false },
    { id: 'round_10', name: 'Ten Pin', desc: 'Complete 10 rounds', unlocked: false },
    { id: 'round_20', name: 'Pyramid Master', desc: 'Complete 20 rounds', unlocked: false },
    { id: 'defeat_coily', name: 'Snake Charmer', desc: 'Defeat Coily once', unlocked: false },
    { id: 'defeat_10', name: 'Pest Control', desc: 'Defeat 10 enemies', unlocked: false },
    { id: 'defeat_50', name: 'Exterminator', desc: 'Defeat 50 enemies', unlocked: false },
    { id: 'score_10k', name: 'High Roller', desc: 'Score 10,000 points', unlocked: false },
    { id: 'score_50k', name: 'Score King', desc: 'Score 50,000 points', unlocked: false },
    { id: 'score_100k', name: 'Legend', desc: 'Score 100,000 points', unlocked: false },
    { id: 'speed_clear', name: 'Speed Demon', desc: 'Complete a Speed round', unlocked: false },
    { id: 'zen_5', name: 'Zen Master', desc: 'Clear 5 Zen rounds', unlocked: false },
    { id: 'challenge_clear', name: 'Challenge Accepted', desc: 'Clear a Challenge round', unlocked: false },
    { id: 'perfect', name: 'Perfect Round', desc: 'Clear a round without dying', unlocked: false },
    { id: 'play_10', name: 'Marathon Runner', desc: 'Play 10 games', unlocked: false },
    { id: 'play_50', name: 'Veteran', desc: 'Play 50 games', unlocked: false },
    { id: 'disc_use', name: 'Disc Jockey', desc: 'Use a flying disc', unlocked: false },
    { id: 'cubes_100', name: 'Color Wizard', desc: 'Change 100 cubes total', unlocked: false },
  ];
}

function loadStats(): CareerStats {
  try {
    const raw = localStorage.getItem('qbert_stats');
    if (raw) return JSON.parse(raw) as CareerStats;
  } catch { /* ignore */ }
  return { gamesPlayed: 0, roundsCleared: 0, enemiesDefeated: 0, cubesHopped: 0, highScore: 0 };
}

function loadAchievements(): Achievement[] {
  const achs = defaultAchievements();
  try {
    const raw = localStorage.getItem('qbert_achievements');
    if (raw) {
      const saved = JSON.parse(raw) as string[];
      for (const a of achs) {
        if (saved.includes(a.id)) a.unlocked = true;
      }
    }
  } catch { /* ignore */ }
  return achs;
}

export function saveStats(s: CareerStats): void {
  try { localStorage.setItem('qbert_stats', JSON.stringify(s)); } catch { /* ignore */ }
}

export function saveAchievements(achs: Achievement[]): void {
  try {
    const ids = achs.filter(a => a.unlocked).map(a => a.id);
    localStorage.setItem('qbert_achievements', JSON.stringify(ids));
  } catch { /* ignore */ }
}

export function cubePos(row: number, col: number): { x: number; y: number; z: number } {
  const x = (col - row * 0.5) * STRIDE;
  const y = (PYRAMID_ROWS - 1 - row) * ROW_DROP;
  const z = row * STRIDE * 0.6;
  return { x, y, z };
}

export function isValidCube(row: number, col: number): boolean {
  return row >= 0 && row < PYRAMID_ROWS && col >= 0 && col <= row;
}

export const state: GameState = {
  screen: 'menu',
  mode: 'arcade',
  difficulty: 'medium',
  colorScheme: 'cyan',
  round: 1,
  score: 0,
  lives: 3,
  playerRow: 0,
  playerCol: 0,
  hopping: false,
  hopProgress: 0,
  hopFromRow: 0,
  hopFromCol: 0,
  hopToRow: 0,
  hopToCol: 0,
  cubes: [],
  enemies: [],
  discLeft: false,
  discRight: false,
  discUsed: false,
  timer: 120,
  hopsRemaining: 50,
  totalHops: 0,
  roundComplete: false,
  gameOver: false,
  deathAnimating: false,
  deathTimer: 0,
  enemySpawnTimer: 0,
  soundEnabled: true,
  musicEnabled: true,
  stats: loadStats(),
  achievements: loadAchievements(),
  achievementPage: 0,
  pendingInput: null,
  initialized: false,
  combo: 0,
  maxCombo: 0,
  comboTimer: 0,
  powerUps: [],
  activePowerUp: null,
  powerUpSpawnTimer: 0,
  shieldActive: false,
  roundAnnounceTimer: 0,
  freezeActive: false,
  scoreBoostActive: false,
};

export function initCubes(): void {
  state.cubes = [];
  const tgt = state.difficulty === 'hard' && state.round > 2 ? 2 : 1;
  for (let r = 0; r < PYRAMID_ROWS; r++) {
    for (let c = 0; c <= r; c++) {
      state.cubes.push({ row: r, col: c, colorState: 0, targetState: tgt });
    }
  }
}

export function getCube(row: number, col: number): CubeData | undefined {
  return state.cubes.find(c => c.row === row && c.col === col);
}

export function allCubesComplete(): boolean {
  return state.cubes.every(c => c.colorState >= c.targetState);
}

// Audio event bus
export type PowerUpType = 'shield' | 'scoreboost' | 'freeze';

export interface PowerUp {
  type: PowerUpType;
  row: number;
  col: number;
  active: boolean;
  pulsePhase: number;
}

export interface ActivePowerUp {
  type: PowerUpType;
  timeLeft: number;
}

export type AudioEvent = 'hop' | 'color_change' | 'death' | 'round_complete' | 'enemy_spawn' | 'enemy_die' | 'disc_use' | 'menu_click' | 'combo' | 'powerup_collect' | 'powerup_spawn';
const audioListeners: ((evt: AudioEvent) => void)[] = [];
export function onAudioEvent(fn: (evt: AudioEvent) => void): void { audioListeners.push(fn); }
export function emitAudio(evt: AudioEvent): void { for (const fn of audioListeners) fn(evt); }

// Effects event bus
export type EffectEvent = { type: 'hop_land'; x: number; y: number; z: number }
  | { type: 'death'; x: number; y: number; z: number }
  | { type: 'round_complete' }
  | { type: 'enemy_die'; x: number; y: number; z: number };
const effectListeners: ((evt: EffectEvent) => void)[] = [];
export function onEffectEvent(fn: (evt: EffectEvent) => void): void { effectListeners.push(fn); }
export function emitEffect(evt: EffectEvent): void { for (const fn of effectListeners) fn(evt); }

import {
  createSystem,
  Mesh,
  Group,
  BoxGeometry,
  SphereGeometry,
  MeshStandardMaterial,
  Color,
  Vector3,
} from '@iwsdk/core';
import {
  state, initCubes, getCube, allCubesComplete, isValidCube, cubePos,
  PYRAMID_ROWS, CUBE_SIZE, PILLAR_HEIGHT, HOP_DURATION, COLOR_SCHEMES,
  emitAudio, emitEffect, saveStats, saveAchievements,
} from './game-state';
import type { EnemyData, ColorScheme } from './game-state';

function cubeColor(colorState: number, targetState: number, scheme: ColorScheme): number {
  const cs = COLOR_SCHEMES[scheme];
  if (colorState >= targetState) return cs.target;
  if (colorState === 0) return cs.start;
  return cs.mid;
}

export class GameSystem extends createSystem({}) {
  private cubeGroup!: Group;
  private cubeMeshes: Mesh[] = [];
  private playerMesh!: Mesh;
  private enemyMeshes: Map<number, Mesh> = new Map();
  private discMeshes: Mesh[] = [];
  private enemyIdCounter = 0;
  private deathsThisRound = 0;

  init() {
    this.cubeGroup = new Group();
    this.scene.add(this.cubeGroup);
    this.buildPyramid();
    this.createPlayer();
    this.createDiscs();
    state.initialized = true;
  }

  private buildPyramid() {
    for (const m of this.cubeMeshes) this.cubeGroup.remove(m);
    this.cubeMeshes = [];
    initCubes();
    const cs = COLOR_SCHEMES[state.colorScheme];
    for (const cube of state.cubes) {
      const pos = cubePos(cube.row, cube.col);
      const geo = new BoxGeometry(CUBE_SIZE, PILLAR_HEIGHT, CUBE_SIZE);
      const mat = new MeshStandardMaterial({
        color: new Color(cs.start),
        emissive: new Color(cs.start),
        emissiveIntensity: 0.3,
        transparent: true,
        opacity: 0.85,
      });
      const mesh = new Mesh(geo, mat);
      mesh.position.set(pos.x, pos.y, pos.z);
      this.cubeGroup.add(mesh);
      this.cubeMeshes.push(mesh);
    }
  }

  private createPlayer() {
    const geo = new SphereGeometry(CUBE_SIZE * 0.35, 16, 16);
    const mat = new MeshStandardMaterial({
      color: new Color(0xffffff),
      emissive: new Color(0xffffff),
      emissiveIntensity: 0.6,
    });
    this.playerMesh = new Mesh(geo, mat);
    const pos = cubePos(0, 0);
    this.playerMesh.position.set(pos.x, pos.y + PILLAR_HEIGHT * 0.5 + CUBE_SIZE * 0.35, pos.z);
    this.playerMesh.visible = false;
    this.scene.add(this.playerMesh);
  }

  private createDiscs() {
    for (let i = 0; i < 2; i++) {
      const geo = new BoxGeometry(0.4, 0.05, 0.4);
      const mat = new MeshStandardMaterial({
        color: new Color(0xff8800),
        emissive: new Color(0xff8800),
        emissiveIntensity: 0.8,
      });
      const mesh = new Mesh(geo, mat);
      mesh.visible = false;
      this.scene.add(mesh);
      this.discMeshes.push(mesh);
    }
  }

  private positionDiscs() {
    // Left disc at row 3, col -1 position (off pyramid)
    const leftPos = cubePos(3, -1);
    this.discMeshes[0].position.set(leftPos.x - 0.5, leftPos.y, leftPos.z);
    this.discMeshes[0].visible = state.discLeft && state.screen === 'playing';
    // Right disc at row 3, col 4 position
    const rightPos = cubePos(3, 4);
    this.discMeshes[1].position.set(rightPos.x + 0.5, rightPos.y, rightPos.z);
    this.discMeshes[1].visible = state.discRight && state.screen === 'playing';
  }

  startGame() {
    state.round = 1;
    state.score = 0;
    state.lives = state.difficulty === 'easy' ? 5 : 3;
    state.playerRow = 0;
    state.playerCol = 0;
    state.hopping = false;
    state.roundComplete = false;
    state.gameOver = false;
    state.deathAnimating = false;
    state.enemies = [];
    state.enemySpawnTimer = 0;
    state.timer = 120;
    state.hopsRemaining = state.mode === 'challenge' ? 50 : 999;
    state.totalHops = 0;
    this.deathsThisRound = 0;
    state.discLeft = true;
    state.discRight = true;
    state.discUsed = false;
    state.stats.gamesPlayed++;
    saveStats(state.stats);
    this.buildPyramid();
    this.updateCubeColors();
    this.clearEnemyMeshes();
    state.screen = 'playing';
  }

  private startRound() {
    state.playerRow = 0;
    state.playerCol = 0;
    state.hopping = false;
    state.roundComplete = false;
    state.enemies = [];
    state.enemySpawnTimer = 0;
    state.discLeft = true;
    state.discRight = true;
    this.deathsThisRound = 0;
    this.buildPyramid();
    this.updateCubeColors();
    this.clearEnemyMeshes();
  }

  private clearEnemyMeshes() {
    for (const [, mesh] of this.enemyMeshes) {
      this.scene.remove(mesh);
    }
    this.enemyMeshes.clear();
  }

  updateCubeColors() {
    for (let i = 0; i < state.cubes.length; i++) {
      const cube = state.cubes[i];
      const mesh = this.cubeMeshes[i];
      if (!mesh) continue;
      const col = cubeColor(cube.colorState, cube.targetState, state.colorScheme);
      const mat = mesh.material as MeshStandardMaterial;
      mat.color.setHex(col);
      mat.emissive.setHex(col);
    }
  }

  private spawnEnemy() {
    const types: EnemyData['type'][] = state.mode === 'zen' ? [] :
      state.difficulty === 'easy' ? ['coily'] :
      state.difficulty === 'hard' ? ['coily', 'slick', 'sam', 'coily'] :
      ['coily', 'slick', 'sam'];
    if (types.length === 0) return;
    if (state.enemies.length >= (state.difficulty === 'hard' ? 4 : 2)) return;
    const type = types[Math.floor(Math.random() * types.length)];
    const startCol = Math.floor(Math.random() * 2);
    const enemy: EnemyData = {
      type,
      row: 0,
      col: startCol,
      active: true,
      isEgg: type === 'coily',
      moveTimer: 0,
    };
    const id = this.enemyIdCounter++;
    state.enemies.push(enemy);
    // Create mesh
    const geo = new SphereGeometry(CUBE_SIZE * 0.3, 8, 8);
    const color = type === 'coily' ? 0xaa00ff : type === 'slick' ? 0x00ff44 : 0x4488ff;
    const mat = new MeshStandardMaterial({
      color: new Color(color),
      emissive: new Color(color),
      emissiveIntensity: 0.5,
    });
    const mesh = new Mesh(geo, mat);
    const pos = cubePos(0, startCol);
    mesh.position.set(pos.x, pos.y + PILLAR_HEIGHT * 0.5 + CUBE_SIZE * 0.3, pos.z);
    this.scene.add(mesh);
    this.enemyMeshes.set(id, mesh);
    emitAudio('enemy_spawn');
  }

  private moveEnemies(delta: number) {
    const speed = state.difficulty === 'easy' ? 2.5 : state.difficulty === 'hard' ? 1.2 : 1.8;
    const keysToRemove: number[] = [];
    let enemyIdx = 0;
    const meshKeys = Array.from(this.enemyMeshes.keys());

    for (let i = 0; i < state.enemies.length; i++) {
      const enemy = state.enemies[i];
      if (!enemy.active) continue;
      enemy.moveTimer += delta;
      if (enemy.moveTimer < speed) { enemyIdx++; continue; }
      enemy.moveTimer = 0;

      if (enemy.type === 'coily') {
        if (enemy.isEgg) {
          // Egg falls down pyramid
          const dc = Math.random() > 0.5 ? 1 : 0;
          enemy.row++;
          enemy.col += dc;
          if (enemy.row >= PYRAMID_ROWS) {
            enemy.active = false;
            const meshKey = meshKeys[enemyIdx];
            if (meshKey !== undefined) keysToRemove.push(meshKey);
          } else if (enemy.row >= 2) {
            enemy.isEgg = false;
          }
        } else {
          // Chase player
          const dr = state.playerRow > enemy.row ? 1 : state.playerRow < enemy.row ? -1 : 0;
          const dc = state.playerCol > enemy.col ? 1 : state.playerCol < enemy.col ? -1 : 0;
          const newRow = enemy.row + dr;
          const newCol = enemy.col + dc;
          if (isValidCube(newRow, newCol)) {
            enemy.row = newRow;
            enemy.col = newCol;
          } else {
            // Try just moving row
            if (dr !== 0 && isValidCube(enemy.row + dr, enemy.col)) {
              enemy.row += dr;
            }
          }
        }
      } else {
        // Slick/Sam: descend, revert cubes
        const dc = Math.random() > 0.5 ? 1 : 0;
        enemy.row++;
        enemy.col += dc;
        if (!isValidCube(enemy.row, enemy.col)) {
          enemy.active = false;
          const meshKey = meshKeys[enemyIdx];
          if (meshKey !== undefined) keysToRemove.push(meshKey);
        } else {
          const cube = getCube(enemy.row, enemy.col);
          if (cube && cube.colorState > 0) {
            cube.colorState = 0;
          }
        }
      }

      // Update mesh position
      if (enemy.active) {
        const meshKey = meshKeys[enemyIdx];
        const mesh = meshKey !== undefined ? this.enemyMeshes.get(meshKey) : undefined;
        if (mesh) {
          const pos = cubePos(enemy.row, enemy.col);
          mesh.position.set(pos.x, pos.y + PILLAR_HEIGHT * 0.5 + CUBE_SIZE * 0.3, pos.z);
        }
      }
      enemyIdx++;
    }

    for (const key of keysToRemove) {
      const mesh = this.enemyMeshes.get(key);
      if (mesh) this.scene.remove(mesh);
      this.enemyMeshes.delete(key);
    }
    state.enemies = state.enemies.filter(e => e.active);
  }

  private checkCollisions() {
    for (const enemy of state.enemies) {
      if (!enemy.active) continue;
      if (enemy.row === state.playerRow && enemy.col === state.playerCol) {
        this.playerDeath();
        return;
      }
    }
    // Check if player fell off
    if (!isValidCube(state.playerRow, state.playerCol)) {
      this.playerDeath();
    }
  }

  private playerDeath() {
    if (state.deathAnimating || state.gameOver) return;
    state.lives--;
    state.deathAnimating = true;
    state.deathTimer = 1.0;
    this.deathsThisRound++;
    const pos = cubePos(state.playerRow, state.playerCol);
    emitAudio('death');
    emitEffect({ type: 'death', x: pos.x, y: pos.y + 0.5, z: pos.z });
    if (state.lives <= 0) {
      state.gameOver = true;
    }
  }

  private respawnPlayer() {
    state.deathAnimating = false;
    if (state.gameOver) {
      // Update high score
      if (state.score > state.stats.highScore) {
        state.stats.highScore = state.score;
        saveStats(state.stats);
      }
      state.screen = 'results';
      return;
    }
    state.playerRow = 0;
    state.playerCol = 0;
    state.hopping = false;
    // Remove enemies on respawn
    state.enemies = [];
    this.clearEnemyMeshes();
    state.enemySpawnTimer = 0;
  }

  tryHop(dr: number, dc: number) {
    if (state.hopping || state.deathAnimating || state.roundComplete || state.screen !== 'playing') return;
    const newRow = state.playerRow + dr;
    const newCol = state.playerCol + dc;

    // Check for disc usage
    if (!isValidCube(newRow, newCol)) {
      // Check left disc
      if (state.discLeft && newCol < 0 && newRow >= 2 && newRow <= 4) {
        state.discLeft = false;
        state.discUsed = true;
        this.useDisc();
        return;
      }
      // Check right disc
      if (state.discRight && newCol > newRow && newRow >= 2 && newRow <= 4) {
        state.discRight = false;
        state.discUsed = true;
        this.useDisc();
        return;
      }
      // Fall off
      state.hopFromRow = state.playerRow;
      state.hopFromCol = state.playerCol;
      state.hopToRow = newRow;
      state.hopToCol = newCol;
      state.hopping = true;
      state.hopProgress = 0;
      return;
    }

    state.hopFromRow = state.playerRow;
    state.hopFromCol = state.playerCol;
    state.hopToRow = newRow;
    state.hopToCol = newCol;
    state.hopping = true;
    state.hopProgress = 0;
    if (state.mode === 'challenge') state.hopsRemaining--;
    state.totalHops++;
    state.stats.cubesHopped++;
    emitAudio('hop');
    this.checkAchievement('first_hop');
    if (state.stats.cubesHopped >= 100) this.checkAchievement('cubes_100');
  }

  private useDisc() {
    // Transport back to top
    state.playerRow = 0;
    state.playerCol = 0;
    state.hopping = false;
    // Coily falls off
    for (const enemy of state.enemies) {
      if (enemy.type === 'coily' && enemy.active) {
        enemy.active = false;
        state.score += 500;
        state.stats.enemiesDefeated++;
        emitAudio('enemy_die');
        this.checkAchievement('defeat_coily');
      }
    }
    this.checkAchievement('disc_use');
    emitAudio('disc_use');
  }

  private completeHop() {
    state.playerRow = state.hopToRow;
    state.playerCol = state.hopToCol;
    state.hopping = false;

    if (!isValidCube(state.playerRow, state.playerCol)) {
      this.playerDeath();
      return;
    }

    const cube = getCube(state.playerRow, state.playerCol);
    if (cube && cube.colorState < cube.targetState) {
      cube.colorState++;
      state.score += 25;
      emitAudio('color_change');
      this.updateCubeColors();
    }

    const pos = cubePos(state.playerRow, state.playerCol);
    emitEffect({ type: 'hop_land', x: pos.x, y: pos.y + PILLAR_HEIGHT * 0.5, z: pos.z });

    this.checkCollisions();

    if (allCubesComplete()) {
      this.completeRound();
    }
  }

  private completeRound() {
    state.roundComplete = true;
    state.score += 1000;
    state.round++;
    state.stats.roundsCleared++;
    saveStats(state.stats);
    emitAudio('round_complete');
    emitEffect({ type: 'round_complete' });

    if (this.deathsThisRound === 0) this.checkAchievement('perfect');
    this.checkAchievement('round_1');
    if (state.stats.roundsCleared >= 5) this.checkAchievement('round_5');
    if (state.stats.roundsCleared >= 10) this.checkAchievement('round_10');
    if (state.stats.roundsCleared >= 20) this.checkAchievement('round_20');
    if (state.mode === 'speed') this.checkAchievement('speed_clear');
    if (state.mode === 'challenge') this.checkAchievement('challenge_clear');

    // Brief pause then next round
    setTimeout(() => {
      if (state.screen === 'playing') {
        this.startRound();
      }
    }, 2000);
  }

  private checkAchievement(id: string) {
    const ach = state.achievements.find(a => a.id === id);
    if (ach && !ach.unlocked) {
      ach.unlocked = true;
      saveAchievements(state.achievements);
    }
  }

  private updatePlayerMesh() {
    this.playerMesh.visible = state.screen === 'playing';
    if (state.screen !== 'playing') return;

    if (state.deathAnimating) {
      // Player falls/fades
      this.playerMesh.position.y -= 0.05;
      (this.playerMesh.material as MeshStandardMaterial).opacity =
        Math.max(0, state.deathTimer);
      return;
    }

    if (state.hopping) {
      const t = state.hopProgress;
      const fromPos = cubePos(state.hopFromRow, state.hopFromCol);
      const toPos = cubePos(state.hopToRow, state.hopToCol);
      const x = fromPos.x + (toPos.x - fromPos.x) * t;
      const z = fromPos.z + (toPos.z - fromPos.z) * t;
      const baseY = fromPos.y + (toPos.y - fromPos.y) * t;
      const arc = Math.sin(t * Math.PI) * 0.8;
      this.playerMesh.position.set(x, baseY + PILLAR_HEIGHT * 0.5 + CUBE_SIZE * 0.35 + arc, z);
    } else {
      const pos = cubePos(state.playerRow, state.playerCol);
      this.playerMesh.position.set(pos.x, pos.y + PILLAR_HEIGHT * 0.5 + CUBE_SIZE * 0.35, pos.z);
    }
  }

  update(delta: number, _time: number) {
    if (state.screen !== 'playing') {
      this.playerMesh.visible = false;
      for (const [, m] of this.enemyMeshes) m.visible = false;
      for (const d of this.discMeshes) d.visible = false;
      return;
    }

    this.playerMesh.visible = true;
    for (const [, m] of this.enemyMeshes) m.visible = true;

    // Handle pending input
    if (state.pendingInput && !state.hopping && !state.deathAnimating && !state.roundComplete) {
      this.tryHop(state.pendingInput.dr, state.pendingInput.dc);
      state.pendingInput = null;
    }

    // Hop animation
    if (state.hopping) {
      state.hopProgress += delta / HOP_DURATION;
      if (state.hopProgress >= 1) {
        state.hopProgress = 1;
        this.completeHop();
      }
    }

    // Death animation
    if (state.deathAnimating) {
      state.deathTimer -= delta;
      if (state.deathTimer <= 0) {
        this.respawnPlayer();
      }
    }

    // Enemy spawning
    if (!state.deathAnimating && !state.roundComplete && state.mode !== 'zen') {
      state.enemySpawnTimer += delta;
      const spawnInterval = state.difficulty === 'easy' ? 8 : state.difficulty === 'hard' ? 4 : 6;
      if (state.enemySpawnTimer >= spawnInterval) {
        state.enemySpawnTimer = 0;
        this.spawnEnemy();
      }
    }

    // Move enemies
    this.moveEnemies(delta);
    this.updateCubeColors();

    // Speed mode timer
    if (state.mode === 'speed' && !state.deathAnimating && !state.roundComplete) {
      state.timer -= delta;
      if (state.timer <= 0) {
        state.timer = 0;
        state.gameOver = true;
        state.deathAnimating = true;
        state.deathTimer = 1.0;
      }
    }

    // Challenge mode hops
    if (state.mode === 'challenge' && state.hopsRemaining <= 0 && !state.roundComplete) {
      state.gameOver = true;
      state.deathAnimating = true;
      state.deathTimer = 1.0;
    }

    // Score achievements
    if (state.score >= 10000) this.checkAchievement('score_10k');
    if (state.score >= 50000) this.checkAchievement('score_50k');
    if (state.score >= 100000) this.checkAchievement('score_100k');
    if (state.stats.enemiesDefeated >= 10) this.checkAchievement('defeat_10');
    if (state.stats.enemiesDefeated >= 50) this.checkAchievement('defeat_50');
    if (state.stats.gamesPlayed >= 10) this.checkAchievement('play_10');
    if (state.stats.gamesPlayed >= 50) this.checkAchievement('play_50');

    // Zen mode achievement
    if (state.mode === 'zen' && state.stats.roundsCleared >= 5) {
      this.checkAchievement('zen_5');
    }

    // Check collisions
    if (!state.hopping && !state.deathAnimating) {
      this.checkCollisions();
    }

    this.updatePlayerMesh();
    this.positionDiscs();

    // Rotate discs
    for (const d of this.discMeshes) {
      if (d.visible) d.rotation.y += delta * 3;
    }
  }
}

import { createSystem } from '@iwsdk/core';
import { state, onAudioEvent } from './game-state';
import type { AudioEvent } from './game-state';

export class AudioSystem extends createSystem({}) {
  private ctx: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private musicOsc: OscillatorNode | null = null;
  private musicGain: GainNode | null = null;
  private musicPlaying = false;

  init() {
    onAudioEvent((evt: AudioEvent) => this.playSound(evt));
  }

  private ensureContext() {
    if (!this.ctx) {
      this.ctx = new AudioContext();
      this.masterGain = this.ctx.createGain();
      this.masterGain.connect(this.ctx.destination);
      this.masterGain.gain.value = 0.3;
    }
    if (this.ctx.state === 'suspended') {
      this.ctx.resume();
    }
    return this.ctx;
  }

  private playTone(freq: number, duration: number, type: OscillatorType = 'sine', volume = 0.3) {
    if (!state.soundEnabled) return;
    const ctx = this.ensureContext();
    if (!this.masterGain) return;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.value = freq;
    gain.gain.setValueAtTime(volume, ctx.currentTime);
    gain.gain.exponentialRampToValueAtTime(0.001, ctx.currentTime + duration);
    osc.connect(gain);
    gain.connect(this.masterGain);
    osc.start(ctx.currentTime);
    osc.stop(ctx.currentTime + duration);
  }

  private playChord(freqs: number[], duration: number, type: OscillatorType = 'sine') {
    for (const f of freqs) this.playTone(f, duration, type, 0.15);
  }

  private playSound(evt: AudioEvent) {
    switch (evt) {
      case 'hop':
        this.playTone(440, 0.1, 'square', 0.2);
        break;
      case 'color_change':
        this.playTone(660, 0.15, 'sine', 0.25);
        this.playTone(880, 0.15, 'sine', 0.2);
        break;
      case 'death':
        this.playTone(200, 0.3, 'sawtooth', 0.3);
        this.playTone(150, 0.5, 'sawtooth', 0.2);
        break;
      case 'round_complete':
        this.playChord([523, 659, 784], 0.3);
        setTimeout(() => this.playChord([587, 740, 880], 0.4), 200);
        setTimeout(() => this.playChord([659, 784, 1047], 0.5), 400);
        break;
      case 'enemy_spawn':
        this.playTone(300, 0.2, 'triangle', 0.15);
        break;
      case 'enemy_die':
        this.playTone(800, 0.1, 'square', 0.2);
        this.playTone(1200, 0.15, 'square', 0.15);
        break;
      case 'disc_use':
        this.playTone(600, 0.1, 'sine', 0.2);
        this.playTone(900, 0.15, 'sine', 0.2);
        this.playTone(1200, 0.2, 'sine', 0.2);
        break;
      case 'menu_click':
        this.playTone(500, 0.05, 'square', 0.15);
        break;
    }
  }

  private startMusic() {
    if (this.musicPlaying || !state.musicEnabled) return;
    const ctx = this.ensureContext();
    if (!this.masterGain) return;
    this.musicGain = ctx.createGain();
    this.musicGain.gain.value = 0.05;
    this.musicGain.connect(this.masterGain);

    this.musicOsc = ctx.createOscillator();
    this.musicOsc.type = 'sine';
    this.musicOsc.frequency.value = 110;
    this.musicOsc.connect(this.musicGain);
    this.musicOsc.start();
    this.musicPlaying = true;
  }

  private stopMusic() {
    if (!this.musicPlaying) return;
    try {
      this.musicOsc?.stop();
    } catch { /* already stopped */ }
    this.musicOsc = null;
    this.musicGain = null;
    this.musicPlaying = false;
  }

  private updateMusic(time: number) {
    if (!this.musicOsc || !this.musicGain) return;
    // Gentle ambient drone that changes pitch slowly
    const baseFreq = 55 + Math.sin(time * 0.1) * 20;
    this.musicOsc.frequency.value = baseFreq;
    this.musicGain.gain.value = state.musicEnabled ? 0.04 : 0;
  }

  update(_delta: number, time: number) {
    if (state.screen === 'playing') {
      if (!this.musicPlaying && state.musicEnabled) {
        this.startMusic();
      }
      if (this.musicPlaying) {
        this.updateMusic(time);
      }
    } else {
      if (this.musicPlaying) {
        this.stopMusic();
      }
    }

    if (this.masterGain) {
      this.masterGain.gain.value = state.soundEnabled ? 0.3 : 0;
    }
  }
}

import {
  createSystem,
  Group,
  Mesh,
  SphereGeometry,
  MeshBasicMaterial,
  Color,
  AdditiveBlending,
  Vector3,
} from '@iwsdk/core';
import { state, onEffectEvent, COLOR_SCHEMES, cubePos, PYRAMID_ROWS } from './game-state';
import type { EffectEvent } from './game-state';

interface Particle {
  mesh: Mesh;
  velocity: Vector3;
  life: number;
  maxLife: number;
}

export class EffectsSystem extends createSystem({}) {
  private particleGroup!: Group;
  private particles: Particle[] = [];
  private ambientOrbs: Mesh[] = [];

  init() {
    this.particleGroup = new Group();
    this.scene.add(this.particleGroup);
    onEffectEvent((evt: EffectEvent) => this.handleEffect(evt));
    this.createAmbientOrbs();
  }

  private createAmbientOrbs() {
    const cs = COLOR_SCHEMES[state.colorScheme];
    for (let i = 0; i < 15; i++) {
      const geo = new SphereGeometry(0.05 + Math.random() * 0.05, 6, 6);
      const mat = new MeshBasicMaterial({
        color: new Color(cs.accent),
        transparent: true,
        opacity: 0.4,
        blending: AdditiveBlending,
      });
      const orb = new Mesh(geo, mat);
      orb.position.set(
        (Math.random() - 0.5) * 8,
        Math.random() * 6,
        (Math.random() - 0.5) * 8
      );
      this.scene.add(orb);
      this.ambientOrbs.push(orb);
    }
  }

  private spawnParticles(x: number, y: number, z: number, count: number, color: number, speed: number) {
    const cs = COLOR_SCHEMES[state.colorScheme];
    for (let i = 0; i < count; i++) {
      const geo = new SphereGeometry(0.03, 4, 4);
      const mat = new MeshBasicMaterial({
        color: new Color(color || cs.target),
        transparent: true,
        opacity: 1,
        blending: AdditiveBlending,
      });
      const mesh = new Mesh(geo, mat);
      mesh.position.set(x, y, z);
      this.particleGroup.add(mesh);

      const angle = Math.random() * Math.PI * 2;
      const upAngle = Math.random() * Math.PI * 0.5;
      const vel = new Vector3(
        Math.cos(angle) * Math.cos(upAngle) * speed,
        Math.sin(upAngle) * speed + Math.random() * speed * 0.5,
        Math.sin(angle) * Math.cos(upAngle) * speed
      );

      this.particles.push({
        mesh,
        velocity: vel,
        life: 0.5 + Math.random() * 0.5,
        maxLife: 0.5 + Math.random() * 0.5,
      });
    }
  }

  private handleEffect(evt: EffectEvent) {
    const cs = COLOR_SCHEMES[state.colorScheme];
    switch (evt.type) {
      case 'hop_land':
        this.spawnParticles(evt.x, evt.y, evt.z, 8, cs.target, 1);
        break;
      case 'death':
        this.spawnParticles(evt.x, evt.y, evt.z, 20, 0xff0000, 2);
        break;
      case 'round_complete':
        // Spawn particles at each cube
        for (let r = 0; r < PYRAMID_ROWS; r++) {
          for (let c = 0; c <= r; c++) {
            const pos = cubePos(r, c);
            this.spawnParticles(pos.x, pos.y + 0.3, pos.z, 3, cs.target, 1.5);
          }
        }
        break;
      case 'enemy_die':
        this.spawnParticles(evt.x, evt.y, evt.z, 12, 0xaa00ff, 1.5);
        break;
    }
  }

  update(delta: number, time: number) {
    // Update particles
    for (let i = this.particles.length - 1; i >= 0; i--) {
      const p = this.particles[i];
      p.life -= delta;
      if (p.life <= 0) {
        this.particleGroup.remove(p.mesh);
        this.particles.splice(i, 1);
        continue;
      }
      p.velocity.y -= delta * 2; // gravity
      p.mesh.position.add(p.velocity.clone().multiplyScalar(delta));
      const mat = p.mesh.material as MeshBasicMaterial;
      mat.opacity = p.life / p.maxLife;
    }

    // Animate ambient orbs
    const cs = COLOR_SCHEMES[state.colorScheme];
    for (let i = 0; i < this.ambientOrbs.length; i++) {
      const orb = this.ambientOrbs[i];
      const offset = i * 0.7;
      orb.position.y += Math.sin(time * 0.5 + offset) * delta * 0.3;
      orb.position.x += Math.cos(time * 0.3 + offset) * delta * 0.1;
      // Wrap around
      if (orb.position.y > 7) orb.position.y = -1;
      if (orb.position.y < -1) orb.position.y = 7;
      const mat = orb.material as MeshBasicMaterial;
      mat.color.setHex(cs.accent);
      mat.opacity = 0.2 + Math.sin(time + offset) * 0.15;
    }
  }
}

import {
  createSystem,
  PanelUI,
  PanelDocument,
  UIKitDocument,
  UIKit,
  eq,
} from '@iwsdk/core';
import { state, emitAudio, saveStats } from './game-state';
import type { Screen } from './game-state';
import { GameSystem } from './game-system';

// Helper to safely set text on a panel element
function setText(doc: UIKitDocument | undefined, id: string, text: string): void {
  if (!doc) return;
  const el = doc.getElementById(id) as UIKit.Text | undefined;
  el?.setProperties({ text });
}

export class UISystem extends createSystem({
  menuPanel: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/menu.json')] },
  hudPanel: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/hud.json')] },
  pausePanel: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/pause.json')] },
  resultsPanel: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/results.json')] },
  settingsPanel: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/settings.json')] },
  tutorialPanel: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/tutorial.json')] },
  statsPanel: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/stats.json')] },
  achievementsPanel: { required: [PanelUI, PanelDocument], where: [eq(PanelUI, 'config', './ui/achievements.json')] },
}) {
  private panelDocs: Partial<Record<string, UIKitDocument>> = {};
  private panelEntities: Map<string, { visible: boolean }> = new Map();
  private gameSystem!: GameSystem;

  init() {
    const gs = this.world.getSystem(GameSystem);
    if (gs) this.gameSystem = gs;

    // Create panel entities positioned in front of camera
    const panelConfigs = [
      { name: 'menu', config: './ui/menu.json', x: 0, y: 3.5, z: -2 },
      { name: 'hud', config: './ui/hud.json', x: 0, y: 5.5, z: -1 },
      { name: 'pause', config: './ui/pause.json', x: 0, y: 3.5, z: -2 },
      { name: 'results', config: './ui/results.json', x: 0, y: 3.5, z: -2 },
      { name: 'settings', config: './ui/settings.json', x: 0, y: 3.5, z: -2 },
      { name: 'tutorial', config: './ui/tutorial.json', x: 0, y: 3.5, z: -2 },
      { name: 'stats', config: './ui/stats.json', x: 0, y: 3.5, z: -2 },
      { name: 'achievements', config: './ui/achievements.json', x: 0, y: 3.5, z: -2 },
    ];

    for (const pc of panelConfigs) {
      const entity = this.world.createTransformEntity();
      entity.object3D!.position.set(pc.x, pc.y, pc.z);
      entity.object3D!.scale.set(0.7, 0.7, 0.7);
      entity.addComponent(PanelUI, { config: pc.config });
      this.panelEntities.set(pc.name, { visible: false });
    }

    // Subscribe to qualify events for each panel
    this.queries.menuPanel.subscribe('qualify', (entity) => {
      const doc = entity.getValue(PanelDocument, 'document') as UIKitDocument | undefined;
      if (!doc) return;
      this.panelDocs['menu'] = doc;
      this.wireMenuPanel(doc);
    });

    this.queries.hudPanel.subscribe('qualify', (entity) => {
      const doc = entity.getValue(PanelDocument, 'document') as UIKitDocument | undefined;
      if (!doc) return;
      this.panelDocs['hud'] = doc;
    });

    this.queries.pausePanel.subscribe('qualify', (entity) => {
      const doc = entity.getValue(PanelDocument, 'document') as UIKitDocument | undefined;
      if (!doc) return;
      this.panelDocs['pause'] = doc;
      this.wirePausePanel(doc);
    });

    this.queries.resultsPanel.subscribe('qualify', (entity) => {
      const doc = entity.getValue(PanelDocument, 'document') as UIKitDocument | undefined;
      if (!doc) return;
      this.panelDocs['results'] = doc;
      this.wireResultsPanel(doc);
    });

    this.queries.settingsPanel.subscribe('qualify', (entity) => {
      const doc = entity.getValue(PanelDocument, 'document') as UIKitDocument | undefined;
      if (!doc) return;
      this.panelDocs['settings'] = doc;
      this.wireSettingsPanel(doc);
    });

    this.queries.tutorialPanel.subscribe('qualify', (entity) => {
      const doc = entity.getValue(PanelDocument, 'document') as UIKitDocument | undefined;
      if (!doc) return;
      this.panelDocs['tutorial'] = doc;
      this.wireTutorialPanel(doc);
    });

    this.queries.statsPanel.subscribe('qualify', (entity) => {
      const doc = entity.getValue(PanelDocument, 'document') as UIKitDocument | undefined;
      if (!doc) return;
      this.panelDocs['stats'] = doc;
      this.wireStatsPanel(doc);
    });

    this.queries.achievementsPanel.subscribe('qualify', (entity) => {
      const doc = entity.getValue(PanelDocument, 'document') as UIKitDocument | undefined;
      if (!doc) return;
      this.panelDocs['achievements'] = doc;
      this.wireAchievementsPanel(doc);
    });
  }

  private wireMenuPanel(doc: UIKitDocument) {
    const btnPlay = doc.getElementById('btn-play') as UIKit.Text | undefined;
    btnPlay?.addEventListener('click', () => {
      emitAudio('menu_click');
      this.gameSystem.startGame();
    });

    const btnArcade = doc.getElementById('btn-arcade') as UIKit.Text | undefined;
    btnArcade?.addEventListener('click', () => { state.mode = 'arcade'; emitAudio('menu_click'); });

    const btnSpeed = doc.getElementById('btn-speed') as UIKit.Text | undefined;
    btnSpeed?.addEventListener('click', () => { state.mode = 'speed'; emitAudio('menu_click'); });

    const btnZen = doc.getElementById('btn-zen') as UIKit.Text | undefined;
    btnZen?.addEventListener('click', () => { state.mode = 'zen'; emitAudio('menu_click'); });

    const btnChallenge = doc.getElementById('btn-challenge') as UIKit.Text | undefined;
    btnChallenge?.addEventListener('click', () => { state.mode = 'challenge'; emitAudio('menu_click'); });

    const btnSettings = doc.getElementById('btn-settings') as UIKit.Text | undefined;
    btnSettings?.addEventListener('click', () => { state.screen = 'settings'; emitAudio('menu_click'); });

    const btnTutorial = doc.getElementById('btn-tutorial') as UIKit.Text | undefined;
    btnTutorial?.addEventListener('click', () => { state.screen = 'tutorial'; emitAudio('menu_click'); });

    const btnStats = doc.getElementById('btn-stats') as UIKit.Text | undefined;
    btnStats?.addEventListener('click', () => { state.screen = 'stats'; emitAudio('menu_click'); });

    const btnAchievements = doc.getElementById('btn-achievements') as UIKit.Text | undefined;
    btnAchievements?.addEventListener('click', () => { state.screen = 'achievements'; emitAudio('menu_click'); });
  }

  private wirePausePanel(doc: UIKitDocument) {
    const btnResume = doc.getElementById('btn-resume') as UIKit.Text | undefined;
    btnResume?.addEventListener('click', () => { state.screen = 'playing'; emitAudio('menu_click'); });

    const btnRestart = doc.getElementById('btn-restart') as UIKit.Text | undefined;
    btnRestart?.addEventListener('click', () => {
      emitAudio('menu_click');
      this.gameSystem.startGame();
    });

    const btnQuit = doc.getElementById('btn-quit') as UIKit.Text | undefined;
    btnQuit?.addEventListener('click', () => { state.screen = 'menu'; emitAudio('menu_click'); });
  }

  private wireResultsPanel(doc: UIKitDocument) {
    const btnAgain = doc.getElementById('btn-again') as UIKit.Text | undefined;
    btnAgain?.addEventListener('click', () => {
      emitAudio('menu_click');
      this.gameSystem.startGame();
    });

    const btnMenu = doc.getElementById('btn-menu') as UIKit.Text | undefined;
    btnMenu?.addEventListener('click', () => { state.screen = 'menu'; emitAudio('menu_click'); });
  }

  private wireSettingsPanel(doc: UIKitDocument) {
    const btnSound = doc.getElementById('btn-sound') as UIKit.Text | undefined;
    btnSound?.addEventListener('click', () => {
      state.soundEnabled = !state.soundEnabled;
      emitAudio('menu_click');
    });

    const btnMusic = doc.getElementById('btn-music') as UIKit.Text | undefined;
    btnMusic?.addEventListener('click', () => {
      state.musicEnabled = !state.musicEnabled;
      emitAudio('menu_click');
    });

    const btnCyan = doc.getElementById('btn-cyan') as UIKit.Text | undefined;
    btnCyan?.addEventListener('click', () => { state.colorScheme = 'cyan'; emitAudio('menu_click'); });

    const btnGreen = doc.getElementById('btn-green') as UIKit.Text | undefined;
    btnGreen?.addEventListener('click', () => { state.colorScheme = 'green'; emitAudio('menu_click'); });

    const btnMagenta = doc.getElementById('btn-magenta') as UIKit.Text | undefined;
    btnMagenta?.addEventListener('click', () => { state.colorScheme = 'magenta'; emitAudio('menu_click'); });

    const btnGold = doc.getElementById('btn-gold') as UIKit.Text | undefined;
    btnGold?.addEventListener('click', () => { state.colorScheme = 'gold'; emitAudio('menu_click'); });

    const btnEasy = doc.getElementById('btn-easy') as UIKit.Text | undefined;
    btnEasy?.addEventListener('click', () => { state.difficulty = 'easy'; emitAudio('menu_click'); });

    const btnMedium = doc.getElementById('btn-medium') as UIKit.Text | undefined;
    btnMedium?.addEventListener('click', () => { state.difficulty = 'medium'; emitAudio('menu_click'); });

    const btnHard = doc.getElementById('btn-hard') as UIKit.Text | undefined;
    btnHard?.addEventListener('click', () => { state.difficulty = 'hard'; emitAudio('menu_click'); });

    const btnBack = doc.getElementById('btn-back') as UIKit.Text | undefined;
    btnBack?.addEventListener('click', () => { state.screen = 'menu'; emitAudio('menu_click'); });
  }

  private wireTutorialPanel(doc: UIKitDocument) {
    const btnBack = doc.getElementById('btn-back') as UIKit.Text | undefined;
    btnBack?.addEventListener('click', () => { state.screen = 'menu'; emitAudio('menu_click'); });
  }

  private wireStatsPanel(doc: UIKitDocument) {
    const btnBack = doc.getElementById('btn-back') as UIKit.Text | undefined;
    btnBack?.addEventListener('click', () => { state.screen = 'menu'; emitAudio('menu_click'); });
  }

  private wireAchievementsPanel(doc: UIKitDocument) {
    const btnBack = doc.getElementById('btn-back') as UIKit.Text | undefined;
    btnBack?.addEventListener('click', () => { state.screen = 'menu'; emitAudio('menu_click'); });

    const btnPrev = doc.getElementById('btn-prev') as UIKit.Text | undefined;
    btnPrev?.addEventListener('click', () => {
      if (state.achievementPage > 0) state.achievementPage--;
      emitAudio('menu_click');
    });

    const btnNext = doc.getElementById('btn-next') as UIKit.Text | undefined;
    btnNext?.addEventListener('click', () => {
      if (state.achievementPage < 1) state.achievementPage++;
      emitAudio('menu_click');
    });
  }

  private showPanel(name: string): boolean {
    const screenMap: Record<Screen, string> = {
      menu: 'menu',
      playing: 'hud',
      paused: 'pause',
      results: 'results',
      settings: 'settings',
      tutorial: 'tutorial',
      stats: 'stats',
      achievements: 'achievements',
    };
    return screenMap[state.screen] === name;
  }

  private updateHUD() {
    const doc = this.panelDocs['hud'];
    if (!doc) return;
    setText(doc, 'score-val', String(state.score));
    setText(doc, 'lives-val', String(state.lives));
    setText(doc, 'round-val', String(state.round));
    if (state.mode === 'speed') {
      setText(doc, 'timer-val', String(Math.ceil(state.timer)));
    } else if (state.mode === 'challenge') {
      setText(doc, 'timer-val', 'Hops: ' + state.hopsRemaining);
    } else {
      setText(doc, 'timer-val', '');
    }
  }

  private updateResults() {
    const doc = this.panelDocs['results'];
    if (!doc) return;
    setText(doc, 'result-title', state.gameOver ? 'GAME OVER' : 'ROUND COMPLETE');
    setText(doc, 'result-score', 'Score: ' + state.score);
    setText(doc, 'result-round', 'Round: ' + (state.round - 1));
    setText(doc, 'result-hops', 'Total Hops: ' + state.totalHops);
    setText(doc, 'result-high', 'High Score: ' + state.stats.highScore);
  }

  private updateSettings() {
    const doc = this.panelDocs['settings'];
    if (!doc) return;
    setText(doc, 'btn-sound', 'Sound: ' + (state.soundEnabled ? 'ON' : 'OFF'));
    setText(doc, 'btn-music', 'Music: ' + (state.musicEnabled ? 'ON' : 'OFF'));
    setText(doc, 'difficulty-val', 'Difficulty: ' + state.difficulty.toUpperCase());
    setText(doc, 'scheme-val', 'Theme: ' + state.colorScheme.toUpperCase());
  }

  private updateStats() {
    const doc = this.panelDocs['stats'];
    if (!doc) return;
    setText(doc, 'stat-games', 'Games Played: ' + state.stats.gamesPlayed);
    setText(doc, 'stat-rounds', 'Rounds Cleared: ' + state.stats.roundsCleared);
    setText(doc, 'stat-enemies', 'Enemies Defeated: ' + state.stats.enemiesDefeated);
    setText(doc, 'stat-cubes', 'Cubes Hopped: ' + state.stats.cubesHopped);
    setText(doc, 'stat-high', 'High Score: ' + state.stats.highScore);
  }

  private updateAchievements() {
    const doc = this.panelDocs['achievements'];
    if (!doc) return;
    const page = state.achievementPage;
    const start = page * 10;
    for (let i = 0; i < 10; i++) {
      const idx = start + i;
      const ach = state.achievements[idx];
      if (ach) {
        setText(doc, 'ach-' + i, (ach.unlocked ? '[x] ' : '[ ] ') + ach.name + ' - ' + ach.desc);
      } else {
        setText(doc, 'ach-' + i, '');
      }
    }
    setText(doc, 'page-num', 'Page ' + (page + 1) + ' / 2');
  }

  private updateMenu() {
    const doc = this.panelDocs['menu'];
    if (!doc) return;
    setText(doc, 'mode-val', 'Mode: ' + state.mode.toUpperCase());
  }

  update(_delta: number, _time: number) {
    // Toggle panel visibility
    const panelNames = ['menu', 'hud', 'pause', 'results', 'settings', 'tutorial', 'stats', 'achievements'];
    for (const query of [
      this.queries.menuPanel,
      this.queries.hudPanel,
      this.queries.pausePanel,
      this.queries.resultsPanel,
      this.queries.settingsPanel,
      this.queries.tutorialPanel,
      this.queries.statsPanel,
      this.queries.achievementsPanel,
    ]) {
      const idx = [
        this.queries.menuPanel,
        this.queries.hudPanel,
        this.queries.pausePanel,
        this.queries.resultsPanel,
        this.queries.settingsPanel,
        this.queries.tutorialPanel,
        this.queries.statsPanel,
        this.queries.achievementsPanel,
      ].indexOf(query);
      const name = panelNames[idx];
      const shouldShow = this.showPanel(name);
      query.entities.forEach(e => {
        if (e.object3D) e.object3D.visible = shouldShow;
      });
    }

    // Update active panel content
    switch (state.screen) {
      case 'playing': this.updateHUD(); break;
      case 'results': this.updateResults(); break;
      case 'settings': this.updateSettings(); break;
      case 'stats': this.updateStats(); break;
      case 'achievements': this.updateAchievements(); break;
      case 'menu': this.updateMenu(); break;
    }
  }
}

import {
  createSystem,
  Group,
  Mesh,
  BoxGeometry,
  SphereGeometry,
  MeshStandardMaterial,
  MeshBasicMaterial,
  Color,
  AdditiveBlending,
} from '@iwsdk/core';
import { state, cubePos, PYRAMID_ROWS, CUBE_SIZE, PILLAR_HEIGHT, COLOR_SCHEMES } from './game-state';

// Render system handles visual effects: cube edge glow, ambient cube pulsing
export class RenderSystem extends createSystem({}) {
  private edgeGroup!: Group;
  private edgeMeshes: Mesh[] = [];
  private glowTime = 0;

  init() {
    this.edgeGroup = new Group();
    this.scene.add(this.edgeGroup);
    this.buildEdges();
  }

  private buildEdges() {
    // Remove old
    for (const m of this.edgeMeshes) this.edgeGroup.remove(m);
    this.edgeMeshes = [];

    const cs = COLOR_SCHEMES[state.colorScheme];
    for (let r = 0; r < PYRAMID_ROWS; r++) {
      for (let c = 0; c <= r; c++) {
        const pos = cubePos(r, c);
        // Wireframe outline using thin boxes for edges (neon glow effect)
        const edgeSize = CUBE_SIZE + 0.02;
        const geo = new BoxGeometry(edgeSize, PILLAR_HEIGHT + 0.02, edgeSize);
        const mat = new MeshBasicMaterial({
          color: new Color(cs.accent),
          transparent: true,
          opacity: 0.3,
          wireframe: true,
        });
        const mesh = new Mesh(geo, mat);
        mesh.position.set(pos.x, pos.y, pos.z);
        this.edgeGroup.add(mesh);
        this.edgeMeshes.push(mesh);
      }
    }
  }

  update(delta: number, time: number) {
    this.glowTime = time;

    // Pulse edge glow
    const pulse = 0.2 + Math.sin(time * 2) * 0.1;
    const cs = COLOR_SCHEMES[state.colorScheme];

    for (let i = 0; i < this.edgeMeshes.length; i++) {
      const mesh = this.edgeMeshes[i];
      const mat = mesh.material as MeshBasicMaterial;
      mat.opacity = pulse;

      // Update edge color to match current scheme
      mat.color.setHex(cs.accent);

      // Position edges to match cubes (in case pyramid was rebuilt)
      if (i < state.cubes.length) {
        const cube = state.cubes[i];
        const pos = cubePos(cube.row, cube.col);
        mesh.position.set(pos.x, pos.y, pos.z);
      }
    }

    // Rebuild edges if count changed
    if (this.edgeMeshes.length !== state.cubes.length) {
      this.buildEdges();
    }
  }
}

import { createSystem, InputComponent } from '@iwsdk/core';
import { state } from './game-state';
import { GameSystem } from './game-system';

export class InputSystem extends createSystem({}) {
  private gameSystem!: GameSystem;
  private inputCooldown = 0;

  init() {
    const gs = this.world.getSystem(GameSystem);
    if (gs) this.gameSystem = gs;
  }

  update(delta: number, _time: number) {
    if (this.inputCooldown > 0) {
      this.inputCooldown -= delta;
      return;
    }

    if (state.screen === 'playing' && !state.hopping && !state.deathAnimating && !state.roundComplete) {
      this.handlePlayInput();
    }

    if (state.screen === 'playing') {
      this.handlePauseInput();
    }
  }

  private handlePlayInput() {
    const kb = this.input.keyboard;

    // Keyboard: Q/ArrowUp+ArrowLeft = up-left, E/ArrowUp+ArrowRight = up-right
    // A/ArrowDown+ArrowLeft = down-left, D/ArrowDown+ArrowRight = down-right
    let dr = 0;
    let dc = 0;

    if (kb.getKeyDown('KeyQ') || kb.getKeyDown('Numpad7')) {
      dr = -1; dc = -1;
    } else if (kb.getKeyDown('KeyE') || kb.getKeyDown('Numpad9')) {
      dr = -1; dc = 0;
    } else if (kb.getKeyDown('KeyA') || kb.getKeyDown('Numpad1')) {
      dr = 1; dc = 0;
    } else if (kb.getKeyDown('KeyD') || kb.getKeyDown('Numpad3')) {
      dr = 1; dc = 1;
    } else if (kb.getKeyDown('ArrowUp') && kb.getKeyPressed('ArrowLeft')) {
      dr = -1; dc = -1;
    } else if (kb.getKeyDown('ArrowUp') && kb.getKeyPressed('ArrowRight')) {
      dr = -1; dc = 0;
    } else if (kb.getKeyDown('ArrowDown') && kb.getKeyPressed('ArrowLeft')) {
      dr = 1; dc = 0;
    } else if (kb.getKeyDown('ArrowDown') && kb.getKeyPressed('ArrowRight')) {
      dr = 1; dc = 1;
    } else if (kb.getKeyDown('ArrowUp')) {
      dr = -1; dc = 0; // Default up = up-right
    } else if (kb.getKeyDown('ArrowDown')) {
      dr = 1; dc = 0; // Default down = down-left
    } else if (kb.getKeyDown('ArrowLeft')) {
      dr = -1; dc = -1; // left = up-left
    } else if (kb.getKeyDown('ArrowRight')) {
      dr = 1; dc = 1; // right = down-right
    }

    // VR Controller input
    const right = this.input.xr.gamepads.right;
    if (right) {
      const stick = right.getAxesValues(InputComponent.Thumbstick);
      if (stick && (Math.abs(stick.x) > 0.5 || Math.abs(stick.y) > 0.5)) {
        // Map thumbstick to isometric directions
        if (stick.y < -0.5 && stick.x < -0.3) {
          dr = -1; dc = -1; // up-left
        } else if (stick.y < -0.5 && stick.x > 0.3) {
          dr = -1; dc = 0; // up-right
        } else if (stick.y > 0.5 && stick.x < -0.3) {
          dr = 1; dc = 0; // down-left
        } else if (stick.y > 0.5 && stick.x > 0.3) {
          dr = 1; dc = 1; // down-right
        } else if (stick.y < -0.5) {
          dr = -1; dc = 0;
        } else if (stick.y > 0.5) {
          dr = 1; dc = 1;
        } else if (stick.x < -0.5) {
          dr = -1; dc = -1;
        } else if (stick.x > 0.5) {
          dr = 1; dc = 1;
        }
        this.inputCooldown = 0.3;
      }
    }

    if (dr !== 0 || dc !== 0) {
      state.pendingInput = { dr, dc };
      this.inputCooldown = 0.15;
    }
  }

  private handlePauseInput() {
    const kb = this.input.keyboard;
    if (kb.getKeyDown('Escape') || kb.getKeyDown('KeyP')) {
      if (state.screen === 'playing') {
        state.screen = 'paused';
      }
    }

    // VR B button for pause
    const right = this.input.xr.gamepads.right;
    if (right && right.getButtonDown(InputComponent.B_Button)) {
      if (state.screen === 'playing') {
        state.screen = 'paused';
      }
    }
  }
}

import {
  createSystem,
  Group,
  Mesh,
  BoxGeometry,
  CylinderGeometry,
  SphereGeometry,
  MeshStandardMaterial,
  MeshBasicMaterial,
  Color,
  AmbientLight,
  PointLight,
  DirectionalLight,
  AdditiveBlending,
  FogExp2,
} from '@iwsdk/core';
import { COLOR_SCHEMES, state } from './game-state';

export class EnvironmentSystem extends createSystem({}) {
  private envGroup!: Group;
  private floorMesh!: Mesh;
  private pillars: Mesh[] = [];
  private ceilingLights: PointLight[] = [];
  private glowPool!: Mesh;
  private pillarCaps: Mesh[] = [];

  init() {
    this.envGroup = new Group();
    this.scene.add(this.envGroup);

    // Fog for depth
    this.scene.fog = new FogExp2(0x000811, 0.04);

    // Ambient light
    const ambient = new AmbientLight(0x112244, 0.5);
    this.scene.add(ambient);

    // Main directional light
    const dirLight = new DirectionalLight(0x4488cc, 0.8);
    dirLight.position.set(5, 10, 5);
    this.scene.add(dirLight);

    this.createFloor();
    this.createPillars();
    this.createCeilingLights();
    this.createGlowPool();
  }

  private createFloor() {
    // Grid floor using wireframe box
    const floorGeo = new BoxGeometry(30, 0.01, 30);
    const floorMat = new MeshBasicMaterial({
      color: new Color(0x112233),
      transparent: true,
      opacity: 0.6,
      wireframe: true,
    });
    this.floorMesh = new Mesh(floorGeo, floorMat);
    this.floorMesh.position.set(0, -0.5, 0);
    this.envGroup.add(this.floorMesh);

    // Solid dark floor underneath
    const solidGeo = new BoxGeometry(30, 0.005, 30);
    const solidMat = new MeshStandardMaterial({
      color: new Color(0x050510),
      transparent: true,
      opacity: 0.9,
    });
    const solidFloor = new Mesh(solidGeo, solidMat);
    solidFloor.position.set(0, -0.52, 0);
    this.envGroup.add(solidFloor);
  }

  private createPillars() {
    const cs = COLOR_SCHEMES[state.colorScheme];
    const positions = [
      [-6, 0, -6], [6, 0, -6], [-6, 0, 6], [6, 0, 6],
      [-3, 0, -8], [3, 0, -8], [-8, 0, 0], [8, 0, 0],
    ];

    for (const pos of positions) {
      // Pillar body - wireframe cylinder
      const geo = new CylinderGeometry(0.15, 0.15, 10, 6);
      const mat = new MeshBasicMaterial({
        color: new Color(cs.accent),
        transparent: true,
        opacity: 0.15,
        wireframe: true,
      });
      const pillar = new Mesh(geo, mat);
      pillar.position.set(pos[0], 4.5, pos[2]);
      this.envGroup.add(pillar);
      this.pillars.push(pillar);

      // Pillar cap - small glowing sphere
      const capGeo = new SphereGeometry(0.2, 8, 8);
      const capMat = new MeshBasicMaterial({
        color: new Color(cs.accent),
        transparent: true,
        opacity: 0.5,
        blending: AdditiveBlending,
      });
      const cap = new Mesh(capGeo, capMat);
      cap.position.set(pos[0], 9.5, pos[2]);
      this.envGroup.add(cap);
      this.pillarCaps.push(cap);
    }
  }

  private createCeilingLights() {
    const cs = COLOR_SCHEMES[state.colorScheme];
    const positions = [
      [0, 9, 0], [-4, 9, -4], [4, 9, -4], [-4, 9, 4], [4, 9, 4],
    ];

    for (const pos of positions) {
      const light = new PointLight(cs.accent, 0.5, 15);
      light.position.set(pos[0], pos[1], pos[2]);
      this.scene.add(light);
      this.ceilingLights.push(light);
    }
  }

  private createGlowPool() {
    // Floor glow pool under the pyramid
    const geo = new BoxGeometry(5, 0.005, 5);
    const mat = new MeshBasicMaterial({
      color: new Color(COLOR_SCHEMES[state.colorScheme].accent),
      transparent: true,
      opacity: 0.15,
      blending: AdditiveBlending,
    });
    this.glowPool = new Mesh(geo, mat);
    this.glowPool.position.set(0, -0.45, 1.5);
    this.envGroup.add(this.glowPool);
  }

  update(_delta: number, time: number) {
    const cs = COLOR_SCHEMES[state.colorScheme];

    // Pulse ceiling lights
    for (let i = 0; i < this.ceilingLights.length; i++) {
      const light = this.ceilingLights[i];
      light.intensity = 0.3 + Math.sin(time * 0.5 + i * 1.2) * 0.15;
      light.color.setHex(cs.accent);
    }

    // Pulse glow pool
    const poolMat = this.glowPool.material as MeshBasicMaterial;
    poolMat.opacity = 0.1 + Math.sin(time * 0.8) * 0.05;
    poolMat.color.setHex(cs.accent);

    // Update pillar colors
    for (const pillar of this.pillars) {
      (pillar.material as MeshBasicMaterial).color.setHex(cs.accent);
    }
    for (const cap of this.pillarCaps) {
      const capMat = cap.material as MeshBasicMaterial;
      capMat.color.setHex(cs.accent);
      capMat.opacity = 0.3 + Math.sin(time * 1.5) * 0.2;
    }

    // Subtle floor grid color update
    (this.floorMesh.material as MeshBasicMaterial).color.setHex(
      (cs.accent & 0xfefefe) >> 2
    );
  }
}

